func (r *runner) Stop(ctx context.Context) error {
	containerDetails, err := r.driver.FindDevContainer(ctx, r.id)
	if err != nil {
		return fmt.Errorf("find dev container: %w", err)
	} else if containerDetails == nil {
		return nil
