		RunE: func(cobraCmd *cobra.Command, args []string) error {
			ctx := cobraCmd.Context()

			dash := cobraCmd.ArgsLenAtDash()
			var nameArgs, cmdArgs []string
			if dash >= 0 {
				nameArgs = args[:dash]
				cmdArgs = args[dash:]
