func (r *runner) runInitializeCommand(
	ctx context.Context,
	conf *config.DevContainerConfig,
	options UpOptions,
) error {
	if options.Platform.Enabled {
		if len(conf.InitializeCommand) > 0 {
			log.Debug("Skipping initializeCommand on platform")
