	ctx context.Context,
	params *runContainerParams,
) (*config.Result, error) {
	if err := r.resolveDefaultContainerConfig(
		params.parsedConfig.Config,
		params.options,
	); err != nil {
		return nil, err
	}
	return r.runSingleContainer(ctx, params)
}

