func (r *runner) getSubstitutedConfig(
	options provider.CLIOptions,
) (*config.SubstitutedConfig, *config.SubstitutionContext, error) {
	return r.getSubstitutedConfigWithContext(context.Background(), options)
}

func (r *runner) getSubstitutedConfigWithContext(
	ctx context.Context,
	options provider.CLIOptions,
) (*config.SubstitutedConfig, *config.SubstitutionContext, error) {
	rawConfig, err := r.getRawConfigWithContext(ctx, options)
	if err != nil {
		return nil, nil, err
	}
	overlay, err := loadDevContainerOverlay(ctx, options.ExtraDevContainerPath)
	if err != nil {
		return nil, nil, err
	}
	if overlay != nil {
		rawConfig = config.CloneDevContainerConfig(rawConfig)
		if err := applyOverlayPlanningInputs(
			rawConfig,
			overlay,
			r.buildSubstitutionContext(options, rawConfig),
		); err != nil {
			return nil, nil, err
		}
	}
	parsed, substitutionContext, err := r.substitute(options, rawConfig)
	if err != nil {
		return nil, nil, err
	}
	parsed.Overlay = overlay
	return parsed, substitutionContext, nil
}

