func GetRunnerIDFromWorkspace(workspace *provider.Workspace) string {
	if encoding.IsLegacyUID(workspace.UID) {
		return workspace.ID
	}
	return workspace.UID
}

func (r *runner) Up(
	ctx context.Context,
	options UpOptions,
	timeout time.Duration,
	reporter status.Reporter,
) (*config.Result, error) {
	if reporter == nil {
		reporter = status.Nop()
	}
	r.reporter = reporter
	selectionWarning := r.compatibilitySelectionWarning(
		r.effectiveDevContainerSelection(options.CLIOptions),
	)

	log.Debugf(
		"Up devcontainer for workspace %q with timeout %s",
		r.workspaceConfig.Workspace.ID,
		timeout,
	)

	var substitutedConfig *config.SubstitutedConfig
	var substitutionContext *config.SubstitutionContext
	err := status.Run(
		ctx,
		reporter,
		status.Operation{Phase: status.PhaseResolvingConfig},
		func(ctx context.Context) error {
			var resolveErr error
			substitutedConfig, substitutionContext, resolveErr = r.getSubstitutedConfigWithContext(
				ctx,
				options.CLIOptions,
			)
			return resolveErr
		},
	)
	if err != nil {
		return nil, err
	}
	defer cleanupBuildInformation(substitutedConfig.Config)
	defaultSelection := overlayConfigKind(substitutedConfig.Config) == overlayDefaultSelection
	if !defaultSelection {
		if err := r.checkOverlayRecreation(ctx, substitutedConfig, options); err != nil {
			return nil, err
		}
	}

	// Recovery skips initializeCommand: a failing host hook must not block the
	// recovery container.
	switch {
	case options.Recovery:
		status.Skip(reporter, status.PhaseInitializeCommand, "recovery mode")
	case options.Platform.Enabled:
		// Platform workspaces execute initialization remotely; this host-side
		// phase is intentionally not run and must not appear successful.
		status.Skip(reporter, status.PhaseInitializeCommand, "platform mode")
	default:
		err = status.Run(
			ctx,
			reporter,
			status.Operation{Phase: status.PhaseInitializeCommand},
			func(ctx context.Context) error {
				if err := r.runInitializeCommand(
					ctx,
					substitutedConfig.Config,
					options,
				); err != nil {
					return clierr.Recoverable(fmt.Errorf("initialize command: %w", err))
				}
				return nil
			},
		)
		if err != nil {
	options provider.CLIOptions,
) (*config.DevContainerConfig, error) {
	defaultConfig := &config.DevContainerConfig{}
	if options.FallbackImage != "" {
		log.Debugf("Using fallback image %s", options.FallbackImage)
		defaultConfig.ImageContainer = config.ImageContainer{Image: options.FallbackImage}
	} else {
		log.Debug("Try detecting project programming language")
		defaultConfig = language.DefaultConfig(r.localWorkspaceFolder)
	}

	const name = ".devcontainer.json"
	defaultConfig.Origin = path.Join(filepath.ToSlash(r.localWorkspaceFolder), name)
	if err := config.SaveDevContainerJSON(defaultConfig); err != nil {
		return nil, fmt.Errorf("write default devcontainer.json: %w", err)
	}
	if err := r.excludeFromGit(name); err != nil {
		log.Debugf("could not add default devcontainer to git exclude: %v", err)
	}
	return defaultConfig, nil
}

func (r *runner) getSubstitutedConfig(
	options provider.CLIOptions,
) (*config.SubstitutedConfig, *config.SubstitutionContext, error) {
	return r.getSubstitutedConfigWithContext(context.Background(), options)
}

func (r *runner) getSubstitutedConfigWithContext(
	ctx context.Context,
	options provider.CLIOptions,
) (*config.SubstitutedConfig, *config.SubstitutionContext, error) {
	rawConfig, err := r.getRawConfigWithContext(ctx, options)
	if err != nil {
		return nil, nil, err
	}
	overlay, err := loadDevContainerOverlay(ctx, options.ExtraDevContainerPath)
	if err != nil {
		return nil, nil, err
	}
	if overlay != nil {
		rawConfig = config.CloneDevContainerConfig(rawConfig)
		if err := applyOverlayPlanningInputs(
			rawConfig,
			overlay,
			r.buildSubstitutionContext(options, rawConfig),
		); err != nil {
			return nil, nil, err
		}
	}
	parsed, substitutionContext, err := r.substitute(options, rawConfig)
	if err != nil {
		return nil, nil, err
	}
	parsed.Overlay = overlay
	return parsed, substitutionContext, nil
}

// substitute resolves devcontainer.json variables and applies CLI overrides,
// returning the substituted config alongside the substitution context used.
func (r *runner) substitute(
