	TermModeFallback = "fallback"
	defaultTerm      = "xterm-256color"
	termModeUsage    = "PTY TERM selection mode: auto, strict, fallback"
	installUsage     = "Install local TERM terminfo on remote before PTY"
)

var (
	isTerminalFunc = func(fd uintptr) bool {
		return term.IsTerminal(int(fd)) // #nosec G115 -- fd is always a valid file descriptor
	}
	makeInputRawTerm    = pty.MakeInputRaw
	makeOutputRawTerm   = pty.MakeOutputRaw
	restoreTerminalFunc = pty.RestoreTerminal
)

type SSHSessionOptions struct {
	TermMode        string
	InstallTerminfo bool
}

type StartSSHSessionOptions struct {
	User            string
	Command         string
	AgentForwarding bool
	SessionOptions  SSHSessionOptions
	OpenTransport   func(context.Context) (transport.ManagedConn, error)
	Exec            ExecFunc
	Stderr          io.Writer
}

type RunSSHSessionOptions struct {
	Command         string
	AgentForwarding bool
	SessionOptions  SSHSessionOptions
	Stderr          io.Writer
}

// NewSSHCmd creates a new ssh command.
func NewSSHCmd(flags *flags.GlobalFlags) *cobra.Command {
	cmd := &SSHCmd{
		GlobalFlags: flags,
	}
	sshCmd := &cobra.Command{
		Use:   "ssh [name]",
		Short: "SSH into the machine",
		RunE: func(cobraCmd *cobra.Command, args []string) error {
			return cmd.Run(cobraCmd.Context(), args)
		},
	}

	cliflags.Add(sshCmd,
		cliflags.String(&cmd.Command, names.Command, "",
			"The command to execute on the remote machine"),
		cliflags.Bool(&cmd.AgentForwarding, names.AgentForwarding, false,
			"If true, will forward the local ssh keys"),
		cliflags.String(&cmd.TermMode, names.TermMode, TermModeAuto, termModeUsage),
		cliflags.Bool(&cmd.InstallTerminfo, names.InstallTerminfo, false, installUsage),
	)
	_ = sshCmd.RegisterFlagCompletionFunc(
		names.TermMode,
		func(*cobra.Command, []string, string) ([]string, cobra.ShellCompDirective) {
			return []string{
				TermModeAuto,
				TermModeStrict,
				TermModeFallback,
			}, cobra.ShellCompDirectiveNoFileComp
		},
	)
	return sshCmd
}

// Run runs the command logic.
func (cmd *SSHCmd) Run(ctx context.Context, args []string) error {
	if !isValidTermMode(cmd.TermMode) {
		return fmt.Errorf(
			"invalid --term-mode %q: expected one of auto, strict, fallback",
			cmd.TermMode,
		)
	}

	devsyConfig, err := config.LoadConfig(cmd.Context, cmd.Provider)
	if err != nil {
		return err
	}

	machineClient, err := workspace.GetMachine(devsyConfig, args)
	if err != nil {
		return err
	}

	streamer := log.NewJSONLogStreamer(log.StreamerOptions{
		FallbackLevel:       log.LevelInfo,
		DetectLevelPrefixes: true,
	})
	defer func() { _ = streamer.Close() }()

	// Get the timeout from the context options
	timeout := config.ParseTimeOption(devsyConfig, config.ContextOptionAgentInjectTimeout)

	// start the ssh session
	return StartSSHSession(ctx, StartSSHSessionOptions{
		Command:         cmd.Command,
		AgentForwarding: cmd.AgentForwarding,
		SessionOptions: SSHSessionOptions{
			TermMode:        cmd.TermMode,
			InstallTerminfo: cmd.InstallTerminfo,
		},
		Exec: func(ctx context.Context, stdin io.Reader, stdout io.Writer, stderr io.Writer) error {
			c := strings.Builder{}
			_, _ = fmt.Fprintf(&c, "'%s' internal ssh-server --stdio", machineClient.AgentPath())
			if cmd.Debug {
				_, _ = c.WriteString(" --debug")
			}
			command := c.String()
			return devagent.InjectAgent(ctx, &devagent.InjectOptions{
				Exec: func(ctx context.Context, command string, stdin io.Reader, stdout io.Writer, stderr io.Writer) error {
					return machineClient.Command(ctx, client.CommandOptions{
						Command:   command,
						Stdin:     stdin,
						Stdout:    stdout,
						Stderr:    stderr,
						RawStdout: true,
					})
				},
				IsLocal:         machineClient.AgentLocal(),
				RemoteAgentPath: machineClient.AgentPath(),
				DownloadURL:     machineClient.AgentURL(),
				Command:         command,
				Stdin:           stdin,
				Stdout:          stdout,
				Stderr:          stderr,
				Timeout:         timeout,
			})
		},
		Stderr: streamer,
	})
}

type ExecFunc func(ctx context.Context, stdin io.Reader, stdout io.Writer, stderr io.Writer) error

func StartSSHSession(ctx context.Context, options StartSSHSessionOptions) error {
	openTransport := options.OpenTransport
	if openTransport == nil {
		if options.Exec == nil {
			return errors.New("open transport or exec function is required")
		}
		openTransport = func(ctx context.Context) (transport.ManagedConn, error) {
			return transport.OpenCallbackConn(ctx, func(
				ctx context.Context,
				stdin io.Reader,
				stdout io.Writer,
			) error {
				return options.Exec(ctx, stdin, stdout, options.Stderr)
			}, transport.CallbackConnOptions{
				LocalAddr:  transport.NewAddr("machine"),
				RemoteAddr: transport.NewAddr("provider"),
			})
		}
	}

	conn, err := openTransport(ctx)
	if err != nil {
		return err
	}
	return transport.RunManaged(transport.RunManagedOptions{
		Parent:        ctx,
		Conn:          conn,
		TransportSide: transport.SideProvider,
		Metadata:      transport.LogMetadata{Mode: "machine", TransportImpl: "callback"},
		Handler: func(ctx context.Context) error {
			sshClient, err := devssh.ClientFromManagedConn(ctx, conn, devssh.ManagedClientOptions{
				User: options.User,
			})
			if err != nil {
				return err
			}
			defer func() { _ = sshClient.Close() }()

			return RunSSHSession(ctx, sshClient, RunSSHSessionOptions{
				Command:         options.Command,
				AgentForwarding: options.AgentForwarding,
				SessionOptions:  options.SessionOptions,
				Stderr:          options.Stderr,
			})
		},
	})
}

func RunSSHSession(ctx context.Context, sshClient *ssh.Client, options RunSSHSessionOptions) error {
	if options.Stderr == nil {
		options.Stderr = os.Stderr
	}

	sessionCtx, cancel := context.WithCancel(ctx)
	defer cancel()

	session, err := sshClient.NewSession()
	if err != nil {
		return err
	}
	defer func() { _ = session.Close() }()

	if err := configureAgentForwarding(sshClient, session, options.AgentForwarding); err != nil {
		return err
	}

	restoreTerm, err := setupPTYIfNeeded(sessionCtx, sshClient, session, options)
	if err != nil {
		return err
	}
	defer restoreTerm()

	wireSessionStdio(session, options.Stderr)
	if err := startSessionCommand(session, options.Command); err != nil {
		return err
	}

	if err := session.Wait(); err != nil {
		return fmt.Errorf("ssh session: %w", err)
	}

	return nil
}

func setupPTYIfNeeded(
	ctx context.Context,
	sshClient *ssh.Client,
	session *ssh.Session,
	options RunSSHSessionOptions,
) (func(), error) {
	if options.Command != "" {
		return noopRestore, nil
	}

	return setupInteractivePTY(ctx, sshClient, session, options)
}

func configureAgentForwarding(
	sshClient *ssh.Client,
	session *ssh.Session,
	shouldForward bool,
) error {
	authSock := devsshagent.GetSSHAuthSocket()
	if !shouldForward || authSock == "" {
		return nil
	}

	err := devsshagent.ForwardToRemote(sshClient, authSock)
	if err != nil {
		return fmt.Errorf("forward agent: %w", err)
	}

	err = devsshagent.RequestAgentForwarding(session)
	if err != nil {
		return fmt.Errorf("request agent forwarding: %w", err)
	}

	return nil
}

func setupInteractivePTY(
	ctx context.Context,
	sshClient *ssh.Client,
	session *ssh.Session,
	options RunSSHSessionOptions,
) (func(), error) {
	stdin := os.Stdin
	stdout := os.Stdout
	fd := int(stdout.Fd()) // #nosec G115 -- fd is always a valid file descriptor
	if !hasInteractiveTerminal(stdin, stdout) {
		return noopRestore, nil
	}

	restoreTerm, err := makeRawTerm(stdin, stdout)
	if err != nil {
		return noopRestore, err
	}

	startWindowResizeForwarder(ctx, session, fd)

	t := resolvePTYTermWithFallback(ctx, sshClient, options.SessionOptions, options.Stderr)
	width, height := getTerminalSize(fd)
	if err = session.RequestPty(t, height, width, ssh.TerminalModes{}); err != nil {
		restoreTerm()
		return noopRestore, fmt.Errorf("request pty: %w", err)
	}

	return restoreTerm, nil
}

func hasInteractiveTerminal(stdin, stdout *os.File) bool {
	return isTerminalFunc(stdin.Fd()) && isTerminalFunc(stdout.Fd())
}

func makeRawTerm(stdin, stdout *os.File) (func(), error) {
	stdinState, err := makeInputRawTerm(stdin.Fd())
	if err != nil {
		return noopRestore, err
	}
	stdoutState, err := makeOutputRawTerm(stdout.Fd())
	if err != nil {
		_ = restoreTerminalFunc(stdin.Fd(), stdinState)
		return noopRestore, err
	}

	return func() {
		_ = restoreTerminalFunc(stdout.Fd(), stdoutState)
		_ = restoreTerminalFunc(stdin.Fd(), stdinState)
	}, nil
}

func noopRestore() {}

func resolvePTYTermWithFallback(
	ctx context.Context,
	sshClient *ssh.Client,
	sessionOptions SSHSessionOptions,
	stderr io.Writer,
) string {
	t, err := resolvePTYTerm(ctx, sshClient, sessionOptions)
	if err == nil {
		return t
	}

	_, _ = fmt.Fprintf(
		stderr,
		"warning: failed to resolve TERM, falling back to %s: %v\n",
		defaultTerm,
		err,
	)
	return defaultTerm
}

func startWindowResizeForwarder(ctx context.Context, session *ssh.Session, fd int) {
	windowChange := devssh.WatchWindowSize(ctx)
	go func() {
		for {
			select {
			case <-ctx.Done():
				return
			case <-windowChange:
			}

			width, height, err := term.GetSize(fd)
			if err != nil {
				continue
			}
			_ = session.WindowChange(height, width)
		}
	}()
}

func getTerminalSize(fd int) (int, int) {
	width, height := 80, 40
	if w, h, err := term.GetSize(fd); err == nil {
		width, height = w, h
	}

	return width, height
}

func wireSessionStdio(session *ssh.Session, stderr io.Writer) {
	session.Stdin = os.Stdin
	session.Stdout = os.Stdout
	session.Stderr = stderr
}

func startSessionCommand(session *ssh.Session, command string) error {
	if command == "" {
		if err := session.Shell(); err != nil {
			return fmt.Errorf("start ssh session with shell: %w", err)
		}
		return nil
	}

	if err := session.Start(command); err != nil {
		return fmt.Errorf("start ssh session with command %s: %w", command, err)
	}

	return nil
}

func resolvePTYTerm(
	ctx context.Context,
	sshClient *ssh.Client,
	sessionOptions SSHSessionOptions,
) (string, error) {
	localTerm := getLocalTerm()
	mode := getTermMode(sessionOptions)

	switch mode {
	case TermModeStrict:
		return localTerm, nil
	case TermModeFallback:
		return defaultTerm, nil
	case TermModeAuto:
		return resolveAutoPTYTerm(ctx, sshClient, localTerm, sessionOptions.InstallTerminfo)
	default:
		return "", fmt.Errorf(
			"invalid --term-mode %q: expected one of auto, strict, fallback",
			mode,
		)
	}
}

func getLocalTerm() string {
	if termEnv, ok := os.LookupEnv("TERM"); ok && termEnv != "" {
		return termEnv
	}

	return defaultTerm
}

func getTermMode(sessionOptions SSHSessionOptions) string {
	if sessionOptions.TermMode == "" {
		return TermModeAuto
	}

	return sessionOptions.TermMode
}

func resolveAutoPTYTerm(
	ctx context.Context,
	sshClient *ssh.Client,
	localTerm string,
	installTerminfo bool,
) (string, error) {
	supported, err := remoteTerminfoExists(ctx, sshClient, localTerm)
	if err != nil {
		return defaultTerm, nil
	}
	if supported {
		return localTerm, nil
	}
	if !installTerminfo {
		return defaultTerm, nil
	}

	installed, err := installLocalTerminfoOnRemote(ctx, sshClient, localTerm)
	if err != nil || !installed {
		return defaultTerm, nil
	}

	supported, err = remoteTerminfoExists(ctx, sshClient, localTerm)
	if err != nil {
		return defaultTerm, nil
	}

	return termFromSupport(supported, localTerm), nil
}

func termFromSupport(supported bool, term string) string {
	if supported {
		return term
	}

	return defaultTerm
}

func remoteTerminfoExists(ctx context.Context, sshClient *ssh.Client, term string) (bool, error) {
	check := fmt.Sprintf(
		"command -v infocmp >/dev/null 2>&1 && infocmp -x %s >/dev/null 2>&1",
		shellescape.Quote(term),
	)
	command := fmt.Sprintf("sh -lc %s", shellescape.Quote(check))
	code, err := runRemoteCommandWithInput(ctx, sshClient, command, nil)
	if err != nil {
		return false, err
	}

	return code == 0, nil
}

// installLocalTerminfoOnRemote best-effort installs local terminfo on remote.
// It returns (false, nil) when prerequisites are missing or installation exits
// non-zero, because callers should continue with TERM fallback in auto mode.
// It only returns a non-nil error for transport/session failures.
func installLocalTerminfoOnRemote(
	ctx context.Context,
	sshClient *ssh.Client,
	term string,
) (bool, error) {
	// #nosec G204 -- term is validated by the caller
	infocmpCmd := exec.CommandContext(ctx, "infocmp", "-x", term)
	output, err := infocmpCmd.Output()
	if err != nil {
		return false, nil
	}
	if len(output) == 0 {
		return false, nil
	}

	command := "sh -lc 'command -v tic >/dev/null 2>&1 && tic -x - >/dev/null 2>&1'"
	runResult, err := runRemoteCommandWithInput(ctx, sshClient, command, bytes.NewReader(output))
	if err != nil {
		return false, err
	}

	return runResult == 0, nil
}

func streamBytesToWriter(reader io.Reader, writer io.WriteCloser) <-chan error {
	errChan := make(chan error, 1)
	go func() {
		_, copyErr := io.Copy(writer, reader)
		closeErr := writer.Close()
		if copyErr != nil {
			errChan <- copyErr
			return
		}
		errChan <- closeErr
	}()

	return errChan
}

// runRemoteCommandWithInput runs a remote command with optional stdin payload.
// Contract: exit status is returned as the first value; non-zero exits are not
// treated as errors. The error return is reserved for SSH/session failures or
// context cancellation, so callers can decide how to handle command exit codes.
func runRemoteCommandWithInput(
	ctx context.Context,
	sshClient *ssh.Client,
	command string,
	input io.Reader,
) (int, error) {
	session, err := sshClient.NewSession()
	if err != nil {
		return -1, fmt.Errorf("create ssh session: %w", err)
	}
	defer func() { _ = session.Close() }()

	errChan, err := startRemoteInputCopy(session, input)
	if err != nil {
		return -1, err
	}
	defer drainErrChan(errChan)

	if err := session.Start(command); err != nil {
		return -1, fmt.Errorf("start remote command: %w", err)
	}

	return waitRemoteCommand(ctx, session)
}

func startRemoteInputCopy(session *ssh.Session, input io.Reader) (<-chan error, error) {
	if input == nil {
		return nil, nil
	}

	stdin, err := session.StdinPipe()
	if err != nil {
		return nil, fmt.Errorf("get remote stdin: %w", err)
	}

	return streamBytesToWriter(input, stdin), nil
}

func drainErrChan(errChan <-chan error) {
	if errChan == nil {
		return
	}

	<-errChan
}

func waitRemoteCommand(ctx context.Context, session *ssh.Session) (int, error) {
	waitErrCh := make(chan error, 1)
	go func() {
		waitErrCh <- session.Wait()
	}()

	select {
	case <-ctx.Done():
		_ = session.Close()
		return -1, fmt.Errorf("remote command canceled: %w", ctx.Err())
	case err := <-waitErrCh:
		if err == nil {
			return 0, nil
		}

		var exitErr *ssh.ExitError
		if errors.As(err, &exitErr) {
			return exitErr.ExitStatus(), nil
		}

		return -1, fmt.Errorf("run remote command: %w", err)
	}
}

func isValidTermMode(mode string) bool {
	switch mode {
	case "", TermModeAuto, TermModeStrict, TermModeFallback:
		return true
	default:
		return false
	}
}
"}

