// ToEnvironment builds the full environment for provider subprocess execution.
// The provider name is available to subprocesses as PROVIDER_ID (set by GetBaseEnvironment).
// Do NOT add DEVSY_PROVIDER to the subprocess env - it is reserved by the --provider
// CLI flag via inheritFlagsFromEnvironment in cmd/root.go, and setting it would override
// the global provider selection for any child devsy process.
func ToEnvironment(
	workspace *Workspace,
	machine *Machine,
	options map[string]config.OptionValue,
	extraEnv map[string]string,
) []string {
	env := ToOptions(workspace, machine, options)

	// create environment variables for command
	osEnviron := os.Environ()
	for k, v := range env {
		osEnviron = append(osEnviron, k+"="+v)
	}
	for k, v := range extraEnv {
		osEnviron = append(osEnviron, k+"="+v)
	}

	return osEnviron
}

func CombineOptions(
	workspace *Workspace,
	machine *Machine,
	options map[string]config.OptionValue,
) map[string]config.OptionValue {
	providerOptions := map[string]config.OptionValue{}
	if options != nil {
		providerOptions = combineOptions(providerOptions, options)
	}
	if workspace != nil {
		providerOptions = combineOptions(providerOptions, workspace.Provider.Options)
	}
	if machine != nil {
		providerOptions = combineOptions(providerOptions, machine.Provider.Options)
	}
	return providerOptions
}

func ToOptionsWorkspace(workspace *Workspace) map[string]string {
	retVars := map[string]string{}
	if workspace == nil {
		return retVars
