      if (!phase.signal.aborted) phase.abort(new Error("E2E execution ended"));
    },
    close() {
      process.off("SIGHUP", interrupt);
      process.off("SIGINT", interrupt);
      process.off("SIGTERM", interrupt);
    },
  };
